// Prepare memories for AI analysis and consolidation
// Groups by themes and identifies patterns

const prepareMemoriesForAnalysis = () => {
  const memories = $('Read Week Memories').all();

  if (memories.length === 0) {
    return {
      hasMemories: false,
      summary: 'No memories found for the past week.',
      memories: []
    };
  }

  // Group memories by date and source
  const groupedMemories = {};
  const themes = new Set();

  memories.forEach(memory => {
    const date = memory.date;
    if (!groupedMemories[date]) {
      groupedMemories[date] = [];
    }

    groupedMemories[date].push({
      content: memory.content,
      source: memory.source,
      timestamp: memory.created_at
    });

    // Extract potential themes/keywords
    const content = memory.content.toLowerCase();
    if (content.includes('project') || content.includes('work')) themes.add('work');
    if (content.includes('learn') || content.includes('study')) themes.add('learning');
    if (content.includes('error') || content.includes('problem')) themes.add('troubleshooting');
    if (content.includes('reminder') || content.includes('task')) themes.add('tasks');
    if (content.includes('idea') || content.includes('creative')) themes.add('ideas');
  });

  // Create analysis prompt
  const memoryText = Object.entries(groupedMemories)
    .map(([date, dayMemories]) => {
      return `\n## ${date}\n${dayMemories.map(m => `- [${m.source}] ${m.content}`).join('\n')}`;
    })
    .join('\n');

  const analysisPrompt = `Analyze the following week of memories and extract key insights, learnings, and important information worth remembering long-term.

Memories from the past 7 days:
${memoryText}

Detected themes: ${Array.from(themes).join(', ')}

Please provide:
1. Key insights or patterns
2. Important information to remember
3. Lessons learned or mistakes to avoid
4. Any action items or follow-ups needed
5. Personal preferences or behaviors observed

Format as structured insights that would be useful for future reference.`;

  return {
    hasMemories: true,
    totalMemories: memories.length,
    dateRange: {
      start: memories[0].date,
      end: memories[memories.length - 1].date
    },
    themes: Array.from(themes),
    analysisPrompt
  };
};

return prepareMemoriesForAnalysis();

// Parse AI insights and prepare for storage
// Extracts individual insights and categorizes them

const parseInsights = () => {
  const aiResponse = $('AI Memory Consolidator').first().json.response;
  const metadata = $('Memory Analyzer').first().json;

  // Split response into individual insights
  const insights = [];
  const lines = aiResponse.split('\n').filter(line => line.trim());

  let currentCategory = 'general';
  let currentInsight = '';

  for (const line of lines) {
    // Check if it's a category header
    if (line.match(/^#+\s/)) {
      if (currentInsight) {
        insights.push({
          category: currentCategory,
          content: currentInsight.trim(),
          importance: determineImportance(currentInsight)
        });
        currentInsight = '';
      }
      currentCategory = line.replace(/^#+\s/, '').toLowerCase().replace(/[^a-z0-9]/g, '_');
    }
    // Check if it's a bullet point
    else if (line.match(/^[\-\*]\s/) || line.match(/^\d+\.\s/)) {
      if (currentInsight) {
        insights.push({
          category: currentCategory,
          content: currentInsight.trim(),
          importance: determineImportance(currentInsight)
        });
      }
      currentInsight = line.replace(/^[\-\*]\s|^\d+\.\s/, '');
    }
    // Continue building current insight
    else if (line.trim()) {
      currentInsight += (currentInsight ? ' ' : '') + line.trim();
    }
  }

  // Don't forget the last insight
  if (currentInsight) {
    insights.push({
      category: currentCategory,
      content: currentInsight.trim(),
      importance: determineImportance(currentInsight)
    });
  }

  // Determine importance based on keywords and context
  function determineImportance(content) {
    const text = content.toLowerCase();
    if (text.includes('important') || text.includes('critical') || text.includes('must remember')) return 3;
    if (text.includes('useful') || text.includes('lesson') || text.includes('avoid')) return 2;
    return 1;
  }

  return {
    insights,
    processingDate: new Date().toISOString().split('T')[0],
    sourceWeek: metadata.dateRange,
    totalMemoriesProcessed: metadata.totalMemories,
    themes: metadata.themes
  };
};

return parseInsights();

